package org.springframework.samples.petclinic.service;

import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;

import org.springframework.stereotype.Component;

/**
 * Remembers which owner was created for each client-supplied {@code Idempotency-Key},
 * so a create that repeats with an already-seen key can return the originally created
 * owner instead of creating a duplicate.
 */
@Component
public class OwnerCreationIdempotencyStore {

    private final Map<String, Integer> ownerIdsByKey = new ConcurrentHashMap<>();

    /**
     * The id of the owner previously created under {@code key}, or empty if the key has
     * not been seen.
     */
    public Optional<Integer> findOwnerId(String key) {
        return Optional.ofNullable(ownerIdsByKey.get(key));
    }

    /**
     * Remember that the owner with {@code ownerId} was the one created under {@code key}.
     * The first owner recorded for a key wins, so concurrent repeats stay consistent.
     */
    public void remember(String key, Integer ownerId) {
        ownerIdsByKey.putIfAbsent(key, ownerId);
    }
}

